// Gambar kad, dilukis sendiri sebagai SVG (viewBox 100x100). Nombor ikut nombor item SDS.
// Warna latar berputar ikut nombor item, bukan ikut jenis RIASEC, supaya warna tidak membayangkan jenis kepada pelajar.
// Item tanpa gambar di sini guna PIC / PIC_DEFAULT dalam items.js.

const LATAR = ["#FFD9A8", "#BFE6FF", "#FFC9D6", "#C9F0C4", "#E0D0FF", "#FFEFA3"];
const G = {
  ink: "#22303F", kayu: "#C98B4E", kayu2: "#A66B34", besi: "#AEBBC8", besi2: "#7D8C9B", merah: "#EF5B5B", oren: "#FF9F45",
  kuning: "#FFD23F", hijau: "#3CB371", biru: "#3D8BFF", ungu: "#8A63D2", pink: "#FF7EA8", putih: "#FFFFFF", kulit: "#F2B98A"
};
// Gaya garisan sama untuk semua bentuk
const L = `stroke="${G.ink}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"`;

// Topi graduan di penjuru: tanda item ini tentang "mengikuti kursus"
const TOPI = `<g transform="translate(70 8)"><path d="M12 2 26 9 12 16-2 9Z" fill="${G.ink}"/><path d="M4 12v6c5 3 11 3 16 0v-6l-8 4Z" fill="${G.ungu}" ${L}/><path d="M26 9v9" ${L} fill="none"/><circle cx="26" cy="20" r="2" fill="${G.kuning}" ${L}/></g>`;
const BUKU = (warna) => `<path d="M14 66c12-5 24-5 36 2 12-7 24-7 36-2v22c-12-5-24-5-36 2-12-7-24-7-36-2Z" fill="${G.putih}" ${L}/><path d="M50 68v22" ${L}/><path d="M21 72c7-1.500 14-1 22 2M21 79c7-1.500 14-1 22 2M57 74c7-3 14-3.500 22-2M57 81c7-3 14-3.500 22-2" fill="none" stroke="${warna}" stroke-width="2.5" stroke-linecap="round"/>`;
const NOTA = (x, y, warna) => `<g transform="translate(${x} ${y})"><path d="M7 16V2l11-2v14" fill="none" ${L}/><ellipse cx="3.500" cy="17" rx="4.500" ry="3.500" fill="${warna}" ${L}/><ellipse cx="14.500" cy="15" rx="4.500" ry="3.500" fill="${warna}" ${L}/></g>`;
const SPANAR = (t) => `<g transform="${t}"><path d="M-5 30V6a10 10 0 0 1-5-14l7 7 6-3 0-7a10 10 0 0 1 7 16v25a5 5 0 0 1-15 0Z" fill="${G.besi}" ${L}/></g>`;
const GEAR = (x, y, r, warna) => {
  const gigi = [0, 45, 90, 135, 180, 225, 270, 315].map(a => `<rect x="${x - r * .22}" y="${y - r * 1.28}" width="${r * .44}" height="${r * .5}" rx="1.500" fill="${warna}" ${L} transform="rotate(${a} ${x} ${y})"/>`).join("");
  return `${gigi}<circle cx="${x}" cy="${y}" r="${r}" fill="${warna}" ${L}/><circle cx="${x}" cy="${y}" r="${r * .36}" fill="${G.putih}" ${L}/>`;
};
const TAYAR = (x, y, r) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${G.ink}"/><circle cx="${x}" cy="${y}" r="${r * .5}" fill="${G.besi}" ${L}/>`;
const KELALANG = (x, y, s, warna) => `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-7-30h14M-5-30v18L-20 14a6 6 0 0 0 5 9h30a6 6 0 0 0 5-9L5-12v-18" fill="${G.putih}" ${L}/><path d="M-12 1-19 14a5 5 0 0 0 4.500 7.500h29a5 5 0 0 0 4.500-7.500L12 1Z" fill="${warna}"/><path d="M-7-30h14M-5-30v18L-20 14a6 6 0 0 0 5 9h30a6 6 0 0 0 5-9L5-12v-18" fill="none" ${L}/><circle cx="-4" cy="10" r="2.500" fill="${G.putih}"/><circle cx="6" cy="14" r="2" fill="${G.putih}"/></g>`;
const MIKROSKOP = `<path d="M30 86h42v-6H30Z" fill="${G.ink}"/><path d="M62 80c9-9 9-26-3-36" fill="none" stroke="${G.ink}" stroke-width="7" stroke-linecap="round"/><rect x="34" y="66" width="28" height="5" rx="2" fill="${G.besi2}" ${L}/><g transform="rotate(-22 50 40)"><rect x="43" y="16" width="14" height="30" rx="3" fill="${G.biru}" ${L}/><rect x="46" y="9" width="8" height="8" rx="2" fill="${G.ink}"/><rect x="46" y="46" width="8" height="10" rx="1.500" fill="${G.besi}" ${L}/></g>`;
const TOPENG = `<path d="M18 26c10 4 22 4 32 0v22c0 11-7 19-16 19s-16-8-16-19Z" fill="${G.kuning}" ${L}/><circle cx="27" cy="40" r="3" fill="${G.ink}"/><circle cx="41" cy="40" r="3" fill="${G.ink}"/><path d="M25 50c5 7 13 7 18 0" fill="none" ${L}/><path d="M48 44c9 4 21 4 32 0v22c0 11-7 19-16 19s-16-8-16-19Z" fill="${G.ungu}" ${L}/><circle cx="57" cy="58" r="3" fill="${G.ink}"/><circle cx="71" cy="58" r="3" fill="${G.ink}"/><path d="M56 74c5-6 11-6 16 0" fill="none" ${L}/>`;
const GITAR = `<g transform="rotate(35 50 50)"><rect x="46" y="4" width="8" height="46" fill="${G.kayu2}" ${L}/><rect x="43" y="2" width="14" height="10" rx="2" fill="${G.ink}"/><path d="M50 44c9 0 13 6 11 13 8 4 11 11 8 19-3 9-12 12-19 12s-16-3-19-12c-3-8 0-15 8-19-2-7 2-13 11-13Z" fill="${G.oren}" ${L}/><circle cx="50" cy="66" r="6" fill="${G.ink}"/></g>`;
// Orang: (x, y) di bahu, kepala di atas, badan ke bawah (tinggi kira-kira 44 bila s = 1)
const ORANG = (x, y, baju, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><path d="M-15 22c0-15 6-24 15-24s15 9 15 24Z" fill="${baju}" ${L}/><circle cy="-10" r="10" fill="${G.kulit}" ${L}/></g>`;
const HATI = (x, y, s, warna) => `<path d="M0 0c-3-6-12-3-10 4 1 5 10 11 10 11s9-6 10-11c2-7-7-10-10-4Z" fill="${warna}" ${L} transform="translate(${x} ${y}) scale(${s})"/>`;
const PENSEL = (x, y, a) => `<g transform="translate(${x} ${y}) rotate(${a})"><rect x="-4" y="-24" width="8" height="30" fill="${G.kuning}" ${L}/><path d="M-4 6h8l-4 9Z" fill="${G.kulit}" ${L}/><rect x="-4" y="-30" width="8" height="6" fill="${G.pink}" ${L}/></g>`;
const BINTANG = (x, y, r, warna) => `<path d="${[...Array(10)].map((_, i) => {
  const a = Math.PI / 5 * i - Math.PI / 2, d = i % 2 ? r * .45 : r;
  return `${i ? "L" : "M"}${(x + d * Math.cos(a)).toFixed(1)} ${(y + d * Math.sin(a)).toFixed(1)}`;
}).join("")}Z" fill="${warna}" ${L}/>`;
const AWAN = (x, y, warna) => `<path d="M-18 8h34a8 8 0 0 0 0-16a11 11 0 0 0-20-4a12 12 0 0 0-14 20Z" fill="${warna}" ${L} transform="translate(${x} ${y})"/>`;
const BELON = (x, y, warna) => `<path d="M${x} ${y + 15}q-5 10 2 24" fill="none" ${L}/><ellipse cx="${x}" cy="${y}" rx="11" ry="14" fill="${warna}" ${L}/><path d="M${x - 3} ${y + 17}h6l-3-4Z" fill="${warna}" ${L}/>`;
const SYILING = (x, y, n) => [...Array(n)].map((_, i) => `<path d="M${x - 12} ${y - i * 6}v4a12 5 0 0 0 24 0v-4" fill="${G.kuning}" ${L}/><ellipse cx="${x}" cy="${y - i * 6}" rx="12" ry="5" fill="${G.kuning}" ${L}/>`).join("");
const BUIH = (x, y, w, h, warna) => `<path d="M${x} ${y}h${w}v${h}H${x + 16}l-9 8v-8H${x}Z" fill="${warna}" ${L}/>`;
// Tangan atau kaki: garisan tebal berwarna kulit
const ANGGOTA = (d) => `<path d="${d}" fill="none" stroke="${G.ink}" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${G.kulit}" stroke-width="3.500" stroke-linecap="round" stroke-linejoin="round"/>`;
const KALKULATOR = (x, y, s) => `<g transform="translate(${x} ${y}) scale(${s})"><rect x="-22" y="-30" width="44" height="60" rx="5" fill="${G.besi2}" ${L}/><rect x="-16" y="-24" width="32" height="13" rx="2" fill="#CDEBFF" ${L}/>${[-4, 7, 18].map(b => [-16, -4, 8].map(a => `<rect x="${a}" y="${b}" width="8" height="7" rx="1.500" fill="${a === 8 ? G.oren : G.putih}" ${L}/>`).join("")).join("")}</g>`;
const RADIOAKTIF = (x, y) => {
  const p = (r, a) => `${(x + r * Math.cos(a * Math.PI / 180)).toFixed(1)} ${(y + r * Math.sin(a * Math.PI / 180)).toFixed(1)}`;
  return `<circle cx="${x}" cy="${y}" r="26" fill="${G.kuning}" ${L}/>` +
    [-150, -30, 90].map(a => `<path d="M${p(7, a - 30)}L${p(21, a - 30)}A21 21 0 0 1 ${p(21, a + 30)}L${p(7, a + 30)}A7 7 0 0 0 ${p(7, a - 30)}Z" fill="${G.ink}"/>`).join("") +
    `<circle cx="${x}" cy="${y}" r="4.500" fill="${G.ink}"/>`;
};

